<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_auth(); require_once __DIR__.'/../config/database.php';$term=substr(trim((string)($_GET['q']??'')),0,100);$field=(string)($_GET['field']??'tracking');$status=substr(trim((string)($_GET['status']??'')),0,25);$where='1=1';$types='';$values=[];if($term!==''){$column=['tracking'=>'d.id_track','title'=>'d.title','author'=>"CONCAT(u.lname,' ',u.fname)"][$field]??'d.id_track';$where.=" AND $column LIKE ?";$types.='s';$values[]='%'.$term.'%';}if($status!==''){$where.=' AND d.status=?';$types.='s';$values[]=$status;}$sql="SELECT d.id_track,d.title,d.datecreated,d.status,CONCAT_WS(', ',u.lname,NULLIF(CONCAT(u.fname,' ',u.mname),'')) author_name FROM dr_documents d LEFT JOIN dr_users u ON u.id=d.author WHERE $where ORDER BY d.datecreated DESC LIMIT 100";$stmt=$conn->prepare($sql);if($types!==''){$refs=[];$refs[]=&$types;foreach($values as $key=>$_)$refs[]=&$values[$key];call_user_func_array([$stmt,'bind_param'],$refs);}$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$page_title='Search documents';$page_heading='Search documents';$active_page='search';require __DIR__.'/../includes/app-shell.php'; ?>
<section class="panel"><form method="get" class="form-grid"><div class="field"><label for="field">Search by</label><select id="field" name="field"><option value="tracking" <?= $field==='tracking'?'selected':'' ?>>Tracking number</option><option value="title" <?= $field==='title'?'selected':'' ?>>Title</option><option value="author" <?= $field==='author'?'selected':'' ?>>Author</option></select></div><div class="field"><label for="q">Search phrase</label><input id="q" name="q" value="<?= e($term) ?>"></div><div class="field"><label for="status">Document state</label><select id="status" name="status"><option value="">All states</option><option value="open" <?= $status==='open'?'selected':'' ?>>Open</option><option value="closed" <?= $status==='closed'?'selected':'' ?>>Closed</option></select></div><div class="form-actions"><button class="btn" type="submit">Search</button></div></form></section><section class="panel data-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Tracking no.</th><th>Title</th><th>Author</th><th>State</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['datecreated']) ?></td><td><?= e($row['id_track']) ?></td><td><?= e($row['title']) ?></td><td><?= e($row['author_name']) ?></td><td><span class="badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td><a class="btn btn-secondary" href="<?= url('documents/view.php?tracking='.rawurlencode($row['id_track'])) ?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty">No documents matched your search.</div><?php endif; ?></section><?php require __DIR__.'/../includes/footer.php'; ?>
